  background: #eee;
  border: 1px solid #ccc;
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.7rem;
  color: #666;
  transition: all 0.3s ease;
}

:scope .doc-slot.active {
  background: var(--accent, #0056b3);
  color: #fff;
  border-color: var(--accent, #0056b3);
}

:scope .doc-slot.collapsed {
  background: #ccc;
  color: #888;
}

:scope .connection-arrow {
  height: 40px;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

:scope .connection-arrow svg {
  width: 100%;
  height: 100%;
}

:scope .flow-path {
  transition: stroke 0.3s ease, stroke-dasharray 0.3s ease;
}

:scope .flow-head {
  transition: fill 0.3s ease;
}

:scope .flow-label {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-size: 0.75rem;
  color: var(--muted, #666);
  background: rgba(255,255,255,0.8);
  padding: 0 0.25rem;
  white-space: nowrap;
}

:scope .attention-map {
  display: flex;
  align-items: flex-end;
  gap: 4px;
  height: 30px;
  margin-top: 0.5rem;
}

:scope .attn-bar {
  flex: 1;
  background: var(--warm, #d97706);
  border-radius: 2px 2px 0 0;
  transition: height 0.3s ease, background 0.3s ease;
}

:scope .analysis-output {
  border-top: 1px solid var(--line, #eee);
  padding-top: 1rem;
}

:scope .analysis-output h3 {
  font-size: 1rem;
  margin-bottom: 0.5rem;
  color: var(--ink, #333);
}

:scope .text-content {
  font-size: 0.95rem;
  color: var(--ink, #444);
  min-height: 3rem;
}

:scope .source-btn {
  background: transparent;
  border: 1px solid var(--line, #ccc);
  color: var(--muted, #666);
  padding: 0.25rem 0.5rem;
  font-size: 0.8rem;
  border-radius: 4px;
  cursor: pointer;
  margin-top: 0.5rem;
  transition: all 0.2s;
}

:scope .source-btn:hover {
  background: var(--paper, #f0f0f0);
  color: var(--ink, #333);
}

:scope .bias-list {
  list-style: none;
  padding: 0;
  margin: 0 0 1.5rem 0;
}

:scope .bias-list li {
  display: flex;
  gap: 0.75rem;
  margin-bottom: 1rem;
  align-items: flex-start;
}

:scope .bias-icon {
  font-size: 1.2rem;
  flex-shrink: 0;
}

:scope .bias-text {
  font-size: 0.95rem;
  color: var(--ink, #444);
}

:scope .source-ref {
  font-size: 0.8rem;
  color: var(--muted, #888);
  margin-left: 0.5rem;
  font-style: italic;
}

:scope .data-table-container {
  margin-top: 2rem;
}

:scope .simple-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.85rem;
  margin-bottom: 0.5rem;
}

:scope .simple-table th,
:scope .simple-table td {
  border: 1px solid var(--line, #ddd);
  padding: 0.5rem;
  text-align: left;
}

:scope .simple-table th {
  background: #f4f6f8;
  font-weight: 600;
}

:scope .table-note {
  font-size: 0.8rem;
  color: var(--muted, #888);
  margin: 0;
}

:scope .chapter-footer {
  margin-top: 2rem;
  padding-top: 1rem;
  border-top: 1px solid var(--line, #ddd);
}

:scope .limitations-summary h3 {
  font-size: 1.1rem;
  margin-bottom: 0.5rem;
  color: var(--ink, #333);
}

:scope .limitations-summary p {
  font-size: 0.95rem;
  color: var(--muted, #666);
  margin: 0;
}
